import requests
from PIL import Image
import io

def task_func(url):
    try:
        response = requests.get(url, timeout=5, allow_redirects=False)
    except requests.RequestException as exc:
        raise ValueError("The URL is invalid or could not be reached within the timeout period.") from exc

    if not (200 <= response.status_code < 300):
        raise ValueError("The response from the server was not a successful HTTP status code.")

    try:
        image = Image.open(io.BytesIO(response.content))
        image.load()
        return image
    except Exception as exc:
        raise ValueError("The content fetched from the URL is not a valid image format.") from exc
